"""Stage 5 interfaces (contracts only, no implementation). PURE.

Everything Stage 5 builds consumes `NavObservation` (produced by ShadowMonitor.latest_observation) and
must never require a CAD file, a precomputed obstacle layout or a prerecorded route: the map starts
empty (all UNKNOWN) and is grown from depth + odometry. See docs/STAGE5_ARCHITECTURE.md.

A policy's output is an `Intent` - a PROPOSED setpoint. Nothing here publishes it. The eventual
publisher is main's dronehacks_nav/skybeta_node.py (the single approved mission node), after the
Stage 4 gate has clamped it.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Optional, Protocol, Sequence

import numpy as np

UNKNOWN, FREE, OCCUPIED = -1, 0, 1          # same codes as main's dronehacks_nav/mapping.py


@dataclass
class NavObservation:
    t: float                                 # node clock
    odom: object                             # shadow.observation.OdomObs (pose, yaw, world velocity, std)
    depth: Optional[object]                  # shadow.observation.DepthObs, None if no accepted frame
    intrinsics: Optional[object]             # shadow.observation.Intrinsics
    extrinsic: Optional[object]              # shadow.transforms.Extrinsic (body <- camera)
    loc_mode: str                            # OK / DEGRADED / HOVER / ABORT
    safety: dict                             # the latest shadow report (verdict, max_speed, reasons)


class OccupancyMap(Protocol):
    """Persistent 3-D log-odds map with per-voxel timestamps, rolling with the vehicle."""
    def integrate(self, obs: NavObservation) -> None: ...
    def state(self, pts: np.ndarray) -> np.ndarray: ...            # (N,) UNKNOWN/FREE/OCCUPIED
    def last_seen(self, pts: np.ndarray) -> np.ndarray: ...        # (N,) node-clock time, NaN never seen
    def inflated_distance(self, pts: np.ndarray, radius: float) -> np.ndarray: ...   # unknown counts as obstacle
    def recentre(self, centre: np.ndarray) -> None: ...            # rolling window, keeps world coordinates


class ExplorationMemory(Protocol):
    def mark_visited(self, pos: np.ndarray, t: float) -> None: ...
    def visited(self, pts: np.ndarray) -> np.ndarray: ...


class FrontierSelector(Protocol):
    def frontiers(self, m: OccupancyMap) -> np.ndarray: ...       # (K,3) FREE cells bordering UNKNOWN
    def choose(self, m: OccupancyMap, mem: ExplorationMemory, pose: np.ndarray) -> Optional[np.ndarray]: ...


class GoalDetector(Protocol):
    def update(self, obs: NavObservation) -> Optional[np.ndarray]: ...    # goal position (ENU) once detected


@dataclass
class TrajectoryCheck:
    ok: bool
    min_clearance: float                    # metres from the inflated vehicle to OCCUPIED
    unknown_fraction: float                 # share of samples whose swept volume touches UNKNOWN
    first_conflict_t: Optional[float]       # trajectory time of the first violation
    reason: str


class TrajectorySafety(Protocol):
    """3-D check of a complete candidate (A* + clothoid sampled in time): inflated by vehicle radius +
    uncertainty, rejects OCCUPIED and (beyond the stopping distance) UNKNOWN, and dynamic infeasibility."""
    def check(self, p: np.ndarray, t: np.ndarray, m: OccupancyMap) -> TrajectoryCheck: ...


@dataclass
class Intent:
    position: Optional[np.ndarray]          # ENU setpoint proposal
    velocity: Optional[np.ndarray]          # ENU world velocity proposal (organizer caps twist at 1.5 m/s)
    yaw: Optional[float]
    reason: str


class NavPolicy(Protocol):
    def step(self, obs: NavObservation) -> Intent: ...


def check_no_prior_map(sources: Sequence[str]) -> None:
    """Policies declare their inputs; any course/CAD/route input is refused."""
    banned = (".obj", ".sdf", ".ply", "route.json", "course")
    bad = [s for s in sources if any(b in s.lower() for b in banned)]
    if bad:
        raise ValueError("Stage 5 must not depend on a prior map or route: %s" % bad)
